function save(){state.scene=area==='road'?{type:'road',from:road.from,to:road.to}:area==='interior'?{type:'interior',label:room.entry.label}:null;try{localStorage.setItem(SAVE,JSON.stringify(state));$('saveLabel').textContent='Partita salvata su questo dispositivo';}catch{$('saveLabel').textContent='Salvataggio non disponibile: esporta dal menu';}}
