function showMap(){if(mode==='rhythm')return;const current=state.city;let selected=current,zoom=1,lines=false;const links=CITIES.flatMap(c=>neighbors(c.id).filter(id=>id>c.id).map(id=>[c.id,id]));const p=panel('La mappa delle Otto Strade',`<p class="fine">Tocca una città per vedere pass e abilità. Scorri la mappa dopo averla ingrandita.</p><div class="atlas-toolbar"><button class="btn secondary" id="zoomOut" aria-label="Riduci mappa">−</button><button class="btn secondary" id="zoomIn" aria-label="Ingrandisci mappa">+</button><button class="btn secondary" id="mapRoutes" aria-pressed="false">Percorsi</button></div><div class="atlas-scroll"><div class="atlas-surface"><img src="./assets/region-map.jpg" alt="Il mondo delle Otto Strade: campagne, città, montagne e isola"><svg viewBox="0 0 1000 447" class="atlas-routes" aria-hidden="true">${links.map(([a,b])=>`<line data-from="${a}" data-to="${b}" x1="${MAP_POINTS[a][0]*10}" y1="${MAP_POINTS[a][1]*4.47}" x2="${MAP_POINTS[b][0]*10}" y2="${MAP_POINTS[b][1]*4.47}"/>`).join('')}</svg>${CITIES.map(c=>`<button class="atlas-pin ${state.visited.includes(c.id)?'visited':''} ${c.id===current?'here':''}" data-city="${c.id}" style="left:${MAP_POINTS[c.id][0]}%;top:${MAP_POINTS[c.id][1]}%" aria-label="${c.name}, ${c.genre}${c.id===current?', sei qui':''}">${c.id+1}</button>`).join('')}</div></div><div class="atlas-city-list">${CITIES.map(c=>`<button class="btn secondary" data-city="${c.id}">${c.id+1} · ${c.name}</button>`).join('')}</div><section class="map-detail" id="mapDetail" aria-live="polite"></section><section id="journeyDetail" class="journey-detail" aria-live="polite"></section>`,[{label:'Metro · scegli una fermata',run:showMetro},{label:'Musicodex · le abilità',run:showDex},{label:'Chiudi mappa · M',run:close}],'ATLANTE DELLA TOURNÉE');p.classList.add('map-panel');
 function select(id){selected=id;const c=CITIES[id],skills=abilityDex(state).filter(a=>a.city===id),reason=metroReason(state,id)||(!atMetro()?'Raggiungi l’ingresso della metro.':null);p.querySelector('#mapDetail').innerHTML=`<h4>${c.name} · ${c.genre}</h4><p>${id===current?'◆ Sei qui. ':''}${state.visited.includes(id)?'Luogo visitato.':'Fermata da scoprire.'} ${state.passes.includes(id)?'Pass ottenuto.':''}</p><p>${c.text||c.lesson||''}</p>${skills.length?`<p>Abilità acquisite: ${skills.filter(a=>a.learned).length} / ${skills.length}</p>`:''}<button class="btn" id="takeMetro" ${reason?'disabled':''}>${reason||'Raggiungi in metro'}</button>`;p.querySelector('#takeMetro').onclick=()=>travelMetro(id);const route=journeyRoute(state,id),detail=p.querySelector('#journeyDetail');detail.innerHTML=id===current?'<p>Sei qui. Scegli una destinazione per preparare il viaggio.</p>':route?`<h4>Il viaggio verso ${c.name}</h4><ol class="journey-legs">${route.legs.map(l=>`<li><strong>${CITIES[l.from].name} → ${CITIES[l.to].name}</strong><span>${l.mode}${l.mode==='Sentiero'&&state.bicycle?' · percorribile anche in bici':''}</span>${l.requirement?`<p>${l.requirement}</p>`:''}</li>`).join('')}</ol><p class="fine">L’itinerario segue i collegamenti del mondo. Raggiungi le uscite e gli imbarchi per proseguire.</p>`:`<h4>Prima di partire</h4><p>${gate(state,id)||'Raggiungi prima Isola Levante in traghetto da Porto del Sol.'}</p>`;const segments=route?.legs||[];for(const line of p.querySelectorAll('.atlas-routes line')){const a=Number(line.dataset.from),b=Number(line.dataset.to);line.classList.toggle('journey-active',segments.some(l=>(l.from===a&&l.to===b)||(l.from===b&&l.to===a)));}p.querySelector('.atlas-routes').classList.toggle('has-journey',segments.length>0);for(const b of p.querySelectorAll('[data-city]'))b.setAttribute('aria-pressed',String(Number(b.dataset.city)===id));}
 for(const b of p.querySelectorAll('[data-city]'))b.onclick=()=>select(Number(b.dataset.city));function scale(d){zoom=Math.max(1,Math.min(3,zoom+d));p.querySelector('.atlas-surface').style.width=zoom*100+'%';}p.querySelector('#zoomIn').onclick=()=>scale(.5);p.querySelector('#zoomOut').onclick=()=>scale(-.5);p.querySelector('#mapRoutes').onclick=e=>{lines=!lines;p.querySelector('.atlas-routes').classList.toggle('visible',lines);e.currentTarget.setAttribute('aria-pressed',String(lines));};select(selected);}
function showMetro(){const unlocked=state.transport.metro===3;const p=panel('Metro delle Otto Strade',`<p>${unlocked?'Il pass di Arturo permette di tornare nelle città raggiunte. L’isola e la montagna sono servite da pontile, nave e funivia, non dalla metro.':'A Binario Nord completa le missioni di Arturo: prima la bicicletta, poi gli annunci della metro. Le fermate si attivano dopo la prima visita.'}</p><div class="metro-stops">${CITIES.filter(c=>METRO_STOPS.includes(c.id)).map(c=>{const reason=metroReason(state,c.id)||(!atMetro()?'Recati alla stazione metro di questa città.':null);return `<button class="metro-stop ${state.visited.includes(c.id)?'visited':''}" data-stop="${c.id}" ${reason?'disabled':''}><strong>${c.name}</strong><span>${reason||'Fermata aperta · sali a bordo'}</span></button>`;}).join('')}</div>`,[{label:'Torna alla mappa',run:showMap},{label:'Chiudi',run:close}],'VIAGGIO RAPIDO · METRO E COINCIDENZE');for(const b of p.querySelectorAll('[data-stop]'))b.onclick=()=>travelMetro(Number(b.dataset.stop));}
function atMetro(){return area==='town'&&townLayout(state.city).objects.some(o=>o.kind==='metro'&&Math.hypot(o.x-state.x,o.y-state.y)<2.6);}
function travelMetro(to){const reason=metroReason(state,to)||(!atMetro()?'Raggiungi l’ingresso della metro in città.':null);if(reason){toast(reason);return;}const from=state.city;close();fade(()=>{state.city=to;const dest=townLayout(to),pos=metroSpawn(dest).find(p=>isWalkable(dest,p.x,p.y));Object.assign(state,pos||{x:24,y:18},{facing:'south',bike:false});portalCooldown=1;setupTown();save();toast('Metro: '+CITIES[from].name+' → '+CITIES[to].name+(to===9?' · coincidenza traghetto':''));});}
function showDex(){if(mode==='rhythm')return;let filter='all';const all=abilityDex(state),p=panel('Musicodex',`<p>Una pagina per ogni capacità: scoperta, acquisita e perfezionata. Puoi completarle tutte nella stessa estate cambiando strumento in sala prove.</p><div class="dex-total">${all.filter(a=>a.learned).length}<span> / ${all.length} abilità acquisite</span></div><p class="fine">Specialità iniziale: ${INSTRUMENTS[state.starter].name}. Le altre parti della band cambiano insieme alla tua.</p><div class="dex-filters">${[['all','Tutte'],['shared','Ascolto'],['guitar','Chitarra'],['bass','Basso'],['drums','Batteria']].map(([id,label])=>`<button class="btn secondary" data-filter="${id}">${label}</button>`).join('')}</div><div id="dexEntries" class="dex-entries"></div>`,[{label:'La nostra band',run:showBand},{label:'Mappa e metro',run:showMap},{label:'Chiudi',run:close}],'SCOPERTE · PRATICA · PADRONANZA');function draw(){p.querySelector('#dexEntries').innerHTML=all.filter(a=>filter==='all'||a.instrument===filter).map(a=>`<article class="dex-entry ${a.learned?'learned':''}"><span class="dex-icon">${a.learned?'♪':a.discovered?'◉':'?'}</span><div><strong>${a.discovered?a.title:'Capacità da scoprire'}</strong><small>${CITIES[a.city].name} · ${a.instrument==='shared'?'Ascolto':INSTRUMENTS[a.instrument].name}</small><p>${!a.discovered?'Raggiungi questa città.':a.mastered?'★ Perfezionata'+(a.score!==undefined?' · '+a.score+'%':''):a.learned?'Acquisita · '+a.score+'% · raggiungi 85% per perfezionarla.':a.description}</p></div></article>`).join('');for(const b of p.querySelectorAll('[data-filter]'))b.setAttribute('aria-pressed',String(b.dataset.filter===filter));}for(const b of p.querySelectorAll('[data-filter]'))b.onclick=()=>{filter=b.dataset.filter;draw();};draw();}
function instrumentStudio(id){panel('Tre strumenti. La stessa band.',`<p>La tua specialità iniziale resta ${INSTRUMENTS[state.starter].name.toLowerCase()}. Qui puoi scambiare il ruolo con Nico e Vale e completare il Musicodex nella stessa partita.</p><p>Le abilità di una città si acquisiscono superando una prova o un concerto dopo l’enigma locale. La padronanza richiede almeno 85%.</p>`,Object.entries(INSTRUMENTS).map(([key,inst])=>({label:inst.name+(state.instrument===key?' · in uso':''),run:()=>{state.instrument=key;save();updateJournal();openSongBrief(id,'practice');}})).concat([{label:'Apri Musicodex',run:showDex},{label:'Torna in sala',run:close,secondary:true}]),'SALA PROVE · CAMBIA STRUMENTO');}
function showBand(){if(mode==='rhythm')return;const missing=Object.keys(INSTRUMENTS).filter(id=>id!==state.instrument);panel('Ancora senza nome.',`<p>Una band nata in un garage. Il nome lo troveremo per strada.</p><div class="stat-row"><span>Tu</span><strong>${INSTRUMENTS[state.instrument].name}</strong></div><div class="stat-row"><span>Nico</span><strong>${INSTRUMENTS[missing[0]].name}</strong></div><div class="stat-row"><span>Vale</span><strong>${INSTRUMENTS[missing[1]].name}</strong></div><div class="stat-row"><span>Esperienza / livello</span><strong>${state.xp} / ${1+Math.floor(state.xp/100)}</strong></div><div class="stat-row"><span>Luoghi scoperti</span><strong>${state.visited.length} / 12</strong></div><div class="stat-row"><span>Ricordi</span><strong>${state.stories.includes(6)?'La cassetta del lato B':'Un’estate da riempire'}</strong></div><h4>I ricordi della strada</h4><p>${state.memories.length?state.memories.map(k=>{const [a,b]=k.slice(5).split('-').map(Number);return CITIES[a].name+' ↔ '+CITIES[b].name;}).join(' · '):'La prima sosta insieme deve ancora arrivare.'}</p><h4>Il plettro delle Otto Strade</h4><p>Il tempo avanza con gli eventi della storia. Esplorare e riprovare non fa scadere l’estate.</p>${state.puzzles.map(id=>`<p><strong>${CITIES[id].name}</strong> · ${CASES[id]?.clue||''}</p>`).join('')}${mysteryEnding(state)?'<p><strong>Il nastro è ricostruito.</strong> Andrea non cercava un trofeo: chiedeva di restituire il suo nome alla canzone scritta con Riva. Il plettro era il simbolo di quella promessa.</p>':'<p>Raccogli le testimonianze nelle città e confrontale con il nastro di Valdaccordo.</p>'}<p class="fine">Nel prototipo il livello registra i traguardi. Le nuove meccaniche musicali arrivano nei brani, senza bonus che correggano gli errori.</p>`,[{label:'Musicodex · abilità',run:showDex},{label:'Torniamo fuori',run:close}],'LA NOSTRA BAND');}
function settings(){if(mode==='rhythm'){pauseSong();return;}const p=panel('Prima del prossimo pezzo.',`<label>Volume <input id="volume" type="range" min="0" max="1" step="0.05" value="${state.settings.volume}"></label><label>Correzione input: <span id="offsetValue">${state.settings.offset}</span> ms<input id="offset" type="range" min="-250" max="250" step="10" value="${state.settings.offset}"></label><p class="fine">Se devi premere dopo la nota visiva per seguire l’audio, aumenta il valore. La regolazione è manuale; usa la sala prove per verificarla.</p><label>Difficoltà <select id="difficulty"><option value="assist">Accessibile</option><option value="normal">Normale</option><option value="expert">Virtuoso</option></select></label><p class="fine">I salvataggi restano in questo browser. Esporta una copia per conservarli o spostarli.</p>`,[{label:'Salva e chiudi',run:()=>{save();close();}},{label:'Esporta partita',run:exportSave},{label:'Importa partita',run:importSave},{label:'Titolo',run:()=>{saved=validateState(state);welcome();},secondary:true}]);p.querySelector('#difficulty').value=state.settings.difficulty;p.querySelector('#volume').oninput=e=>{state.settings.volume=Number(e.target.value);syncAudio();};p.querySelector('#offset').oninput=e=>{state.settings.offset=Number(e.target.value);p.querySelector('#offsetValue').textContent=e.target.value;};p.querySelector('#difficulty').onchange=e=>{state.settings.difficulty=e.target.value;};}
function exportSave(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='una-estate-in-tour-salvataggio.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const valid=validateState(JSON.parse(await input.files[0].text()));if(!valid)throw Error();state=valid;syncAudio();restoreScene();save();close();toast('Partita importata. Buon viaggio!');}catch{toast('Questo file non è un salvataggio valido.');}};input.click();}
function toggleBike(){if(mode!=='world'||!overlay.hidden)return;if(!state.bicycle){toast('Una vecchia bici ti aspetta a Binario Nord.');return;}state.bike=!state.bike;save();updateJournal();toast(state.bike?'In sella. La strada sembra più corta.':'Torni a camminare.');}

// Local canvas rendering with illustrated sprite atlases.
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.ceil(w),Math.ceil(h));}
function text(s,x,y,color='#f4e8c8',size=10,align='left'){ctx.fillStyle=color;ctx.font=`${size}px monospace`;ctx.textAlign=align;ctx.fillText(s,Math.round(x),Math.round(y));ctx.textAlign='left';}
function hash(x,y){return Math.abs(Math.sin(x*127.1+y*311.7+state.city*19.3)*43758.5453)%1;}
function character(x,y,color='#cf9368',variant=0,moving=false,bike=false){drawCharacter(ctx,x,y,{color,variant,moving,bike,walk,facing:variant?'south':state.facing});}
function drawStage(x,y,genre){smoothStage(ctx,x,y,genre);}
function roomItems(kind){if(kind==='house')return [[7,24,23,170,100],[4,14,14,145,120],[5,20,14,64,120],[3,34,14,100,130],[0,15,22,135,100],[1,34,22,90,150],[2,33,27,115,110],[15,26,11,110,85],[6,25,18,120,100]];
 if(kind==='school')return [[14,24,12,190,100],[13,14,17,110,140],[12,18,21,120,100],[12,30,21,120,100],[3,35,14,100,130],[15,13,11,90,80]];
 if(kind==='garage')return [[7,24,23,190,100],[8,14,15,130,110],[10,34,15,125,90],[11,34,24,120,85],[9,20,14,50,100],[3,14,25,90,120],[15,31,11,100,85]];
 return [[7,24,23,180,100],[13,16,16,130,155],[8,33,16,130,110],[3,33,24,100,135],[2,15,25,130,110],[15,25,11,120,90]];}
function drawInterior(){const cam=cameraFor(state.x,state.y,W,H);ctx.save();ctx.translate(-cam.x,-cam.y);rect(0,0,WIDTH*T,HEIGHT*T,'#294238');const sx=10*T,sy=7*T,rw=28*T,rh=22*T;ctx.fillStyle='#e2d3b1';ctx.beginPath();ctx.roundRect(sx,sy,rw,rh,12);ctx.fill();rect(sx,sy,rw,70,room.entry.kind==='garage'?'#a5b29a':'#b7c5ae');for(let y=11;y<29;y++)rect(sx,y*T,rw,1,'#b6a58644');for(let x=11;x<38;x+=3)rect(x*T,11*T,1,18*T,'#b6a58622');
 text(room.entry.label,24*T,8*T,'#59745b',16,'center');const items=roomItems(room.entry.kind);for(const [id,x,y,w,h]of items)if(id===7)drawSprite(ctx,'interiors',1,3,x*T,y*T,w,h);
 const actors=items.filter(i=>i[0]!==7).map(([id,x,y,w,h])=>({depth:y*T,draw:()=>drawSprite(ctx,'interiors',Math.floor(id/4),id%4,x*T,y*T,w,h)}));
 if(room.entry.kind==='garage')actors.push({depth:13*T,draw:()=>smoothStage(ctx,24*T,13*T,'SALA PROVE')});for(const o of objects)actors.push({depth:o.y*T,draw:()=>drawCharacter(ctx,o.x*T,o.y*T,{variant:o.sprite||1,portrait:o.portrait??null,facing:o.facing||'south'})});actors.push({depth:state.y*T,draw:()=>drawCharacter(ctx,state.x*T,state.y*T,{facing:state.facing,moving:hasMoved,walk})});actors.sort((a,b)=>a.depth-b.depth).forEach(o=>o.draw());rect(23*T,28*T,2*T,1.2*T,'#e7c891');text('↓ USCITA',24*T,27.8*T,'#6d7959',10,'center');ctx.restore();}
function drawWorld(ts){if(area==='interior')drawInterior();else renderWorld(ctx,{layout,state,area,walk,moving:hasMoved,near,time:ts,W,H});}
function drawRhythm(){if(song)drawConcert(ctx,{song,time:songTime(),W,H,instrument:state.instrument});}
function canMove(x,y){if(area==='interior')return x>10.5&&x<37.5&&y>10.8&&y<29&&!solids.some(b=>x>b.x-.3&&x<b.x+b.w+.3&&y>b.y-.3&&y<b.y+b.h+.3);return isWalkable(layout,x,y);}
let saveClock=0;
function update(dt){if(mode==='rhythm'){tickSong();return;}hasMoved=false;if(!overlay.hidden||transitioning)return;portalCooldown=Math.max(0,portalCooldown-dt);let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(dx||dy){path=[];tapObject=null;}else if(path.length){const next=path[0],dist=Math.hypot(next.x-state.x,next.y-state.y);if(dist<.15){path.shift();if(!path.length&&tapObject){near=tapObject;tapObject=null;interact();return;}}else{dx=(next.x-state.x)/dist;dy=(next.y-state.y)/dist;}}
 if(dx||dy){state.facing=facingFor(dx,dy,state.facing);const length=Math.hypot(dx,dy),speed=state.bike&&area!=='interior'?8:4.5;const delta=path.length?stepToward(state,path[0],dt*speed):stepToward({x:0,y:0},{x:dx/length,y:dy/length},dt*speed),steps=Math.max(1,Math.ceil(Math.hypot(delta.dx,delta.dy)/.15));dx=delta.dx/steps;dy=delta.dy/steps;for(let i=0;i<steps;i++){if(canMove(state.x+dx,state.y)){state.x+=dx;hasMoved=true;}if(canMove(state.x,state.y+dy)){state.y+=dy;hasMoved=true;}}if(hasMoved){walk+=dt;saveClock+=dt;if(saveClock>3){saveClock=0;save();}}}
 automaticPassages();if(transitioning||!overlay.hidden)return;near=null;let best=2.25;for(const o of objects){if(o.building||o.kind==='exit'||o.kind==='roadBack'||o.kind==='roadEnd')continue;const dist=Math.hypot(o.x-state.x,o.y-state.y);if(dist<best){best=dist;near=o;}}
 if(near&&(near.kind==='npc'||area==='interior'))near.facing=facingFor(state.x-near.x,state.y-near.y);$('prompt').hidden=!near;if(near)$('prompt').textContent='E / PARLA · '+near.label;canvas.setAttribute('aria-label',`Mondo di gioco: ${CITIES[state.city].name}${area==='interior'?', '+room.entry.label:''}. Posizione ${state.x.toFixed(1)}, ${state.y.toFixed(1)}. Direzione ${state.facing}.`);}
function frame(ts){const dt=Math.min(.12,(ts-last)/1000);last=ts;update(dt);ctx.clearRect(0,0,W,H);if(mode==='rhythm')drawRhythm(ts);else drawWorld(ts);requestAnimationFrame(frame);}
document.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key)&&!['INPUT','SELECT'].includes(e.target.tagName))e.preventDefault();if(e.repeat)return;if(mode==='rhythm'){if(key===' '){if(song?.paused){overlay.querySelector('button')?.click();}else pauseSong();return;}if(!overlay.hidden)return;const lane=INSTRUMENTS[state.instrument].labels.map(k=>k.toLowerCase()).indexOf(key);if(lane>=0)pressLane(lane);return;}if(!overlay.hidden){if(key==='m'&&overlay.querySelector('.map-panel'))close();else if(key==='escape'&&!overlay.querySelector('.narrative')&&!overlay.querySelector('.chapter-title')&&!overlay.querySelector('.instrument-choices'))close();return;}if(key==='e'||key==='enter')interact();else if(key==='b')toggleBike();else if(key==='m')showMap();else if(key==='escape')settings();else keys.add(key);});
document.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(mode==='rhythm'){const lane=INSTRUMENTS[state.instrument].labels.map(k=>k.toLowerCase()).indexOf(e.key.toLowerCase());if(lane>=0)releaseLane(lane);}});
window.addEventListener('blur',()=>{keys.clear();if(song&&!song.paused)pauseSong();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(song&&!song.paused)pauseSong();if(mode==='world'&&state.introDone)save();}});
document.querySelectorAll('[data-move]').forEach(b=>{const k={up:'arrowup',down:'arrowdown',left:'arrowleft',right:'arrowright'}[b.dataset.move];b.onpointerdown=e=>{if(!overlay.hidden||mode!=='world')return;e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(k);};b.onpointerup=b.onpointercancel=()=>keys.delete(k);});
$('touchAction').onclick=interact;$('touchBike').onclick=toggleBike;$('mapBtn').onclick=showMap;$('bandBtn').onclick=showDex;$('settingsBtn').onclick=settings;$('pauseSong').onclick=pauseSong;$('exitSong').onclick=()=>exitSong();$('soundBtn').onclick=()=>{state.settings.muted=!state.settings.muted;syncAudio();save();};
canvas.addEventListener('pointerdown',e=>{if(mode!=='world'||!overlay.hidden||transitioning)return;canvas.focus();const r=canvas.getBoundingClientRect(),scale=Math.min(r.width/W,r.height/H),ox=(r.width-W*scale)/2,oy=(r.height-H*scale)/2;const px=(e.clientX-r.left-ox)/scale,py=(e.clientY-r.top-oy)/scale;if(px<0||px>W||py<0||py>H)return;const cam=cameraFor(state.x,state.y,W,H,layout),x=(px+cam.x)/T,y=(py+cam.y)/T;
 const object=objects.find(o=>Math.hypot(o.x-x,o.y-y)<1.7||o.building&&x>o.building.x&&x<o.building.x+o.building.w&&y>o.building.y&&y<o.building.y+o.building.h);const edge=layout.gates.find(g=>Math.hypot(g.x-x,g.y-y)<2);const target=object?{x:object.x,y:object.y}:edge?{x:edge.x,y:edge.y}:{x,y};path=findPath(state,target,canMove,WIDTH,HEIGHT);tapObject=object&&!object.building?object:null;
 if(!path.length&&tapObject&&Math.hypot(state.x-object.x,state.y-object.y)<2.25){near=object;tapObject=null;interact();}});
function fitCanvas(){const r=canvas.getBoundingClientRect();W=Math.round(H*r.width/r.height);canvas.width=W;canvas.height=H;}
window.addEventListener('resize',fitCanvas);fitCanvas();setupTown();welcome();requestAnimationFrame(frame);

function portraitCard(id){return `<div class="person-card"><span class="person-portrait" style="--px:${id%4*100/3}%;--py:${Math.floor(id/4)*100/3}%"></span><p><strong>${PEOPLE[id][0]}</strong><br>${PEOPLE[id][1]}</p></div>`;}
function showResident(o){if(state.city===3&&state.transport.bike===1){state.transport.bike=2;save();updateJournal();panel('Una pompa per ripartire',portraitCard(o.portrait??11)+'<p>«Arturo cerca questa? L’avevo portata al campeggio. Ecco la pompa: riportagliela e sistemate la bici insieme.»</p>',[{label:'Riporta la pompa ad Arturo',run:close}],'MISSIONE · LA BICI DEL CAMPEGGIO');return;}const id=o.portrait??15,c=CASES[state.city];panel(o.label,portraitCard(id)+`<p>${state.city===0?'«Il maestro Riva suonava qui con altri tre ragazzi. Al mercatino ho visto una custodia con un plettro disegnato: chiedi a Nino, sul fiume.»':c?c.scene:'«Una vecchia band percorse queste stesse strade. All’archivio di Valdaccordo c’è ancora il loro nastro.»'}</p>`,[{label:c?'Annota e cerca l’insegnante':'Annota il racconto',run:close}],'VOCI DEL PAESE');}
function showRival(o){const id=o.portrait;const text=state.stage==='rival'?['«La piazza è pronta. Vediamo se sapete ascoltarvi quando arrivano gli errori.»','«Elia esagera. Io voglio sentire il vostro basso. Ci vediamo davanti al palco.»','«Prima di salire conto quattro volte. Se perdo il conto faccio finta fosse un fill.»'][id]:state.passes.length>=5?['«Vi ho sentiti alla radio. Quando tornate su quel palco voglio esserci.»','«Il vostro suono è cambiato. Avete imparato a lasciare spazio.»','«Mi insegnate quel passaggio? Senza dirlo a Elia.»'][id]:['«Il festival è lontano per tutti. Anche noi dobbiamo allenarci.»','«Un consiglio: ascolta Vale quando smette di suonare. Anche le pause dicono qualcosa.»','«Ho rotto una bacchetta. La tengo per ricordarmi di non stringere troppo.»'][id];panel(o.label+' · Alta Tensione',portraitCard(id)+`<p>${text}</p>`,[{label:state.stage==='rival'?'Verso la sfida':'Ci vediamo per strada',run:()=>state.stage==='rival'?songBrief(0,'rival'):close()}],'I RIVALI');}
function rememberRoad(){const key='road:'+Math.min(road.from,road.to)+'-'+Math.max(road.from,road.to);if(!state.memories.includes(key)){state.memories.push(key);save();}return key;}
function showRoadEncounter(o){const key='road:'+Math.min(road.from,road.to)+'-'+Math.max(road.from,road.to),scenes=['Un acquazzone vi ferma sotto una tettoia. Nico protegge lo strumento con la felpa. Qualcuno tiene il tempo sulle gocce.','Una catena è saltata vicino al campeggio. Vale tiene la bici mentre il viaggiatore cerca il suo provino nella custodia.','La radio del chiosco perde il segnale. Sami vuole registrare una piccola esibizione prima che il proprietario chiuda.','Un musicista ha dimenticato il resto del gruppo. Aspettando, vi propone di accompagnare la melodia che ricorda.','Il traghetto è in ritardo. I passeggeri sono stanchi; un piccolo concerto può cambiare l’attesa.'];const event=scenes[(road.from+road.to)%scenes.length];const id=o.portrait??12,c=CASES[road.to]||CASES[road.from];panel(o.label+' · Una sosta lungo il viaggio',portraitCard(id)+`<p>${state.memories.includes(key)?'«Vi ricordate la nostra sosta? Ho ancora quella registrazione.»':event}</p><p>Vale posa lo zaino: «Possiamo fermarci. Non tutte le cose importanti sono su un palco.»</p>`,[{label:'Fermiamoci a provare',run:()=>{rememberRoad();songBrief(CITIES[road.to].type==='music'?road.to:1,'practice');}},{label:'Ascolta la testimonianza',run:()=>{rememberRoad();panel('Un nome sul nastro',`<p>«Riva vi ha parlato del plettro? Chiedete delle Otto Strade. Il mistero non riguarda chi suonava più veloce, ma un nome che manca.»</p><p>${c?.fact||'Nel taccuino potete ritrovare le testimonianze raccolte.'}</p>`,[{label:'Riprendiamo il viaggio',run:close}]);}},{label:'Salutiamo e proseguiamo',run:close,secondary:true}],'INCONTRO SUL SENTIERO');}
function showCase(c){const q=CASES[c.id];panel(q.title,portraitCard(({1:3,2:4,4:5,5:6,7:7,8:8,9:9,10:10})[c.id])+`<p>${q.scene}</p><p><strong>Gli appunti trovati:</strong> ${q.hint}</p><p class="fine">${q.fact}</p>`,[{label:state.puzzles.includes(c.id)?'Riapri il laboratorio':'Esamina gli appunti',run:()=>orderCase(c)},{label:'Torna in città',run:close,secondary:true}],'INDAGINE MUSICALE · '+c.genre.toUpperCase());}
function orderCase(c){const q=CASES[c.id],answer=[],order=q.parts.map((_,i)=>i).reverse();const p=panel(q.title,`<p>${q.scene}</p><p id="caseHint">${q.hint}</p><div class="case-parts"></div><ol id="caseAnswer"></ol><p id="caseFeedback" aria-live="polite">Scegli i frammenti nell’ordine indicato dagli indizi.</p>`,[{label:'Ricomincia',run:()=>orderCase(c)},{label:'Confronta gli appunti',run:()=>{if(caseComplete(q.parts,answer)){panel('Il disegno torna. Ora ascoltiamo.',`<p>${q.fact}</p><p>Avete ricostruito gli appunti: prima del concerto l’insegnante propone una breve verifica di ascolto e memoria. Questa seconda prova usa quattro suoni simbolici.</p>`,[{label:'Ascolta e rispondi',run:()=>startPuzzle(c)}]);}else p.querySelector('#caseFeedback').textContent='Qualcosa non coincide. Rileggi gli appunti e ricostruisci la sequenza: nessun indizio va perso.';}},{label:'Esci dal laboratorio',run:close,secondary:true}],'RICOSTRUZIONE · POI PROVA DI ASCOLTO');for(const id of order){const b=document.createElement('button');b.className='btn secondary';b.textContent=q.parts[id];b.onclick=()=>{answer.push(id);b.disabled=true;const li=document.createElement('li');li.textContent=q.parts[id];p.querySelector('#caseAnswer').appendChild(li);};p.querySelector('.case-parts').appendChild(b);}}

function showTransportQuest(){const q=state.transport;if(q.bike===0){panel('La bici del campeggio',portraitCard(13)+'<p>«Questa bici è ferma da mesi. La pompa l’ha presa qualcuno al campeggio: chiedete ai ragazzi in piazza e riportatemela. La sistemiamo insieme.»</p>',[{label:'Accetta · cerca la pompa',run:()=>{q.bike=1;save();updateJournal();close();toast('Missione: chiedi ai ragazzi in piazza della pompa.');}},{label:'Più tardi',run:close,secondary:true}],'MISSIONE · UN MEZZO PER PARTIRE');return;}if(q.bike===1){panel('Manca ancora la pompa','<p>«Chiedete ai ragazzi del campeggio, qui in piazza. Senza quella non possiamo ripartire.»</p>',[{label:'Cerchiamola',run:close}]);return;}if(q.bike===2){q.bike=3;state.bicycle=true;if(!state.stories.includes(3))state.stories.push(3);save();updateJournal();panel('La prima pedalata','<p>Arturo gonfia le gomme, controlla la bici con voi e ve la consegna. Nico tiene il manubrio, Vale ride: «Adesso voglio vedere il mare.»</p><p><strong>Missione completata · Bicicletta ottenuta.</strong> Usa B oppure BICI. Arturo ha anche un altro lavoro per voi.</p>',[{label:'Chiedi della metro',run:showTransportQuest},{label:'In sella',run:close}],'RICOMPENSA · BICICLETTA');return;}if(q.metro===0){panel('Le voci delle Otto Strade',portraitCard(13)+'<p>«La metro ha aperto i collegamenti con gli altri paesi, ma al nostro sportello manca la sequenza degli annunci musicali. Nella stazione c’è il vecchio nastro: ritrovate l’ordine delle frasi e riportatemelo. Per ringraziarvi vi darò il pass della tournée.»</p>',[{label:'Accetta · entra nella stazione',run:()=>{q.metro=1;save();updateJournal();close();toast('Missione: entra nella Stazione Nord e ricomponi gli annunci.');}},{label:'Più tardi',run:close,secondary:true}],'MISSIONE · IL PASS DELLA METRO');return;}if(q.metro===1){panel('La stazione vi aspetta','<p>«Il nastro è dentro la Stazione Nord. Ricomponete gli annunci e poi tornate da me.»</p>',[{label:'Andiamo alla stazione',run:close}]);return;}if(q.metro===2){q.metro=3;save();updateJournal();panel('Una fermata dopo l’altra','<p>Arturo ascolta il nastro. «Adesso sì. Quando sentirete queste note, saprete di essere sulla strada di casa.»</p><p><strong>Missione completata · Pass metro ottenuto.</strong> Raggiungi un ingresso contrassegnato M nelle città servite. Puoi viaggiare tra fermate già visitate. Per l’isola usa nave o pontile; per Monteferro la funivia.</p>',[{label:'Apri le fermate',run:showMetro},{label:'Torniamo in città',run:close}],'RICOMPENSA · PASS METRO');return;}showMetro();}
function metroAnnouncement(){let index=0;const sequence=[0,2,1,3];const p=panel('Il nastro degli annunci','<p>Sulla custodia: «Partenza: campi. Poi il ponte, quindi le officine. Ultima fermata: i binari». Quattro frammenti sono fuori ordine.</p><p>Ogni frammento ha un segnale sonoro: ascoltalo toccando la scheda. Ricostruisci il percorso indicato sulla custodia.</p><div class="case-parts"></div><p id="metroAnswer" aria-live="polite">0 / 4 annunci ordinati</p>',[{label:'Riparti dall’inizio',run:metroAnnouncement},{label:'Torna in stazione',run:close}],'MISSIONE · LE VOCI DELLE OTTO STRADE');for(const i of [3,1,0,2]){const b=document.createElement('button');b.className='btn secondary';b.textContent=['Campi · Borgo delle Cicale','Officine · Officina','Ponte · Rivafosca','Binari · Binario Nord'][i];b.onclick=async()=>{try{await audio.init();audio.tone(220*Math.pow(2,[0,7,4,12][i]/12),audio.ctx.currentTime,.3,'triangle',.12);}catch{}if(i===sequence[index]){index++;p.querySelector('#metroAnswer').textContent=index+' / 4 annunci ordinati';if(index===4){state.transport.metro=2;save();updateJournal();panel('Il nastro è pronto','<p>Le fermate tornano nell’ordine della vecchia linea. Avete recuperato gli annunci: ora riportate il nastro ad Arturo in piazza.</p>',[{label:'Torna da Arturo',run:close}],'MISSIONE · ULTIMO PASSAGGIO');}}else{index=0;p.querySelector('#metroAnswer').textContent='Questo annuncio non segue il precedente. Riparti dai campi e rileggi la custodia.';}};p.querySelector('.case-parts').appendChild(b);}}

function travelConnection(to,label){close();fade(()=>{state.city=to;if(!state.visited.includes(to))state.visited.push(to);const l=townLayout(to),o=l.objects.find(o=>o.kind===(label==='Funivia'?'cable':'ferry'));const pos=o?{x:o.x,y:o.y+1}:metroSpawn(l).find(p=>isWalkable(l,p.x,p.y));Object.assign(state,pos,{facing:'south',bike:false});setupTown();portalCooldown=1;save();toast(label+' · '+CITIES[to].name);});}
function rideCable(){if(state.stage!=='tour'){toast('Prima cominciate la tournée.');return;}const to=state.city===7?6:7;panel('La funivia di Monteferro','<p>Una cabina risale il versante oltre l’accademia. Sotto scorrono il bosco e i tornanti; in alto vi aspettano le case di pietra e la fortezza.</p>',[{label:'Sali · '+CITIES[to].name,run:()=>travelConnection(to,'Funivia')},{label:'Resta qui',run:close}],'COLLEGAMENTO DI MONTAGNA');}
